'use strict';
// Bundle the pinned MediaPipe browser runtime and model as same-origin static assets.
// The generated files are ignored by git and recreated on build/postinstall.
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const root = path.join(__dirname, '..');
const packageRoot = path.join(root, 'node_modules/@mediapipe/tasks-vision');
const assetPath = path.join(root, 'assets/magazine-face/blaze_face_full_range_sparse.tflite.b64');
const dest = path.join(root, 'public/vendor/mediapipe');
const wasmDest = path.join(dest, 'wasm');
const modelDest = path.join(dest, 'models');
const expectedVersion = '1.1.0';
const expectedModelSha256 = '2c3728e6da56f21e21a320433396fb06d40d9088f2247c05e5635a688d45dfe1';

if (!fs.existsSync(path.join(packageRoot, 'package.json'))) throw new Error('Install @mediapipe/tasks-vision before preparing magazine face framing.');
const pkg = JSON.parse(fs.readFileSync(path.join(packageRoot, 'package.json'), 'utf8'));
if (pkg.version !== expectedVersion) throw new Error(`Expected @mediapipe/tasks-vision ${expectedVersion}, got ${pkg.version}. Review and pin the asset runtime before upgrading.`);
fs.mkdirSync(wasmDest, { recursive: true });
fs.mkdirSync(modelDest, { recursive: true });
for (const file of ['vision_bundle.js']) fs.copyFileSync(path.join(packageRoot, file), path.join(dest, file));
for (const file of ['vision_wasm_internal.js', 'vision_wasm_internal.wasm']) fs.copyFileSync(path.join(packageRoot, 'wasm', file), path.join(wasmDest, file));
const model = Buffer.from(fs.readFileSync(assetPath, 'utf8').trim(), 'base64');
const actualModelSha256 = crypto.createHash('sha256').update(model).digest('hex');
if (actualModelSha256 !== expectedModelSha256) throw new Error('Face detector model checksum mismatch.');
fs.writeFileSync(path.join(modelDest, 'blaze_face_full_range_sparse.tflite'), model);
fs.copyFileSync(path.join(root, 'assets/magazine-face/LICENSE'), path.join(dest, 'LICENSE'));
fs.writeFileSync(path.join(dest, 'README.md'), [
  'Generated local browser assets for magazine face-aware framing.',
  '',
  `Runtime: @mediapipe/tasks-vision ${expectedVersion} (Apache-2.0).`,
  'Model: BlazeFace Full Range Sparse, float16, pinned model asset (Apache-2.0).',
  'Model source: https://storage.googleapis.com/mediapipe-models/face_detector/blaze_face_full_range/float16/1/blaze_face_full_range_sparse.tflite',
  'The source photos are analyzed in the browser; only the framed image is uploaded to Paigaam for Canva generation.',
  'MediaPipe documents that image inputs are processed on device and not sent to Google; it may send performance/utilization metrics.',
  'This directory is generated by scripts/prepare-magazine-face.js and is not tracked in git.',
  '',
].join('\n'));
console.log(`[magazines] MediaPipe ${expectedVersion} assets prepared; face model verified (${model.length} bytes).`);
